export const siteOverviewPage = (user: User, site: SiteOverviewData) => {
  const published = site.version === site.publishedVersion;
  const state = published ? 'Published' : 'Draft changes';
  return shell(`${site.name} overview`, `<main class="dashboard-app">${accountMenuCss}${siteOverviewCss}${workbenchHeader(user, site.name)}
  <div class="pc-main">${managementRail(site, 'overview')}
  <section class="pc-workspace"><div class="pc-manage-content"><header class="pc-manage-head"><div><a class="pc-manage-back" href="/"><span aria-hidden="true">←</span> All sites</a><div class="pc-manage-title"><h1>${esc(site.name)}</h1><span class="pc-manage-state ${published ? '' : 'draft'}">${state}</span></div><a class="pc-manage-url" href="${esc(site.url)}" target="_blank" rel="noopener">${esc(site.url.replace(/^https?:\/\//, '').replace(/\/$/, ''))}</a></div><div class="pc-manage-actions"><a class="pc-btn primary" href="/edit/${encodeURIComponent(site.id)}">Edit site</a><a class="pc-btn" href="${esc(site.url)}" target="_blank" rel="noopener">View site</a></div></header>
  <section class="pc-manage-grid" aria-label="Site overview"><a class="pc-manage-preview" href="${esc(site.url)}" target="_blank" rel="noopener"><div class="pc-manage-preview-fallback" aria-hidden="true">${builderMark}<span>Loading site preview…</span></div><iframe src="${esc(site.url)}" loading="eager" tabindex="-1" aria-hidden="true" title=""></iframe><span class="pc-manage-preview-open">Open live site <span aria-hidden="true">↗</span></span></a><aside class="pc-manage-summary"><h2>Site status</h2><p>The current publishing state and your access to this site.</p><dl class="pc-manage-facts"><div><dt>Publishing</dt><dd>${state}</dd></div><div><dt>Access</dt><dd>${site.role === 'owner' ? 'Owner' : 'Content editor'}</dd></div><div><dt>Last edited</dt><dd title="${esc(fullDate(site.updatedAt))}">${esc(relativeTime(site.updatedAt))}</dd></div><div><dt>Last published</dt><dd>${esc(fullDate(site.publishedAt))}</dd></div><div><dt>Current version</dt><dd>v${site.version}</dd></div></dl><div class="pc-manage-next"><h2>${published ? 'Your site is live' : 'Changes are ready to publish'}</h2><p>${published ? 'Open the builder whenever you are ready to make another change.' : 'Review the draft in the builder, then publish when it is ready.'}</p><a class="pc-btn ${published ? '' : 'primary'}" href="/edit/${encodeURIComponent(site.id)}">${published ? 'Edit site' : 'Publish changes'}</a></div></aside></section>
  <div class="pc-manage-sections"><section class="pc-manage-section"><h2>Public address</h2><p>${site.customDomain ? `This site is connected to ${esc(site.customDomain)}.` : 'This site is available on its Pagecraft address.'}</p><div class="pc-copy-row"><code>${esc(site.url)}</code><button class="pc-btn" type="button" data-copy-value="${esc(site.url)}">Copy link</button></div></section><section class="pc-manage-section"><h2>Project export</h2><p>Download an editable Pagecraft project copy for safekeeping or transfer.</p><a class="pc-btn" href="/v1/sites/${encodeURIComponent(site.id)}/packages/site">Download project</a></section></div>
  </div></section></div></main><script>(()=>{const preview=document.querySelector('.pc-manage-preview'),frame=preview?.querySelector('iframe'),label=preview?.querySelector('.pc-manage-preview-fallback span');if(frame){const ready=()=>preview.classList.add('is-ready');const failed=()=>{preview.classList.remove('is-ready');if(label)label.textContent='Preview unavailable';};frame.addEventListener('load',ready,{once:true});frame.addEventListener('error',failed,{once:true});setTimeout(()=>{if(!preview.classList.contains('is-ready'))failed();},7000);}document.querySelectorAll('[data-copy-value]').forEach(button=>button.addEventListener('click',async()=>{const value=button.dataset.copyValue||'';try{await navigator.clipboard.writeText(value);}catch{const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();document.execCommand('copy');field.remove();}const previous=button.textContent;button.textContent='Copied';setTimeout(()=>button.textContent=previous,1600);}));})();</script>`);
};

