export const accountSettingsPage = (
  user: User, data: AccountSettingsData,
  input: { error?: string; message?: string; tab?: AccountSettingsTab } = {}
) => {
  const providers = new Set(data.providers);
  const hasPassword = providers.has('email');
  const sitePercent = Math.min(100, Math.round(data.ownerCount / 3 * 100));
  const storagePercent = Math.min(100, Math.round(data.storage.usedBytes / Math.max(1, data.storage.limitBytes) * 100));
  const joined = data.createdAt || user.createdAt;
  const joinedCopy = joined ? new Intl.DateTimeFormat('en', { dateStyle: 'medium' }).format(new Date(joined)) : '';
  const selectedTab = input.tab || 'profile';
  const tabState = (tab: AccountSettingsTab) => selectedTab === tab
    ? 'aria-selected="true" tabindex="0"'
    : 'aria-selected="false" tabindex="-1"';
  return shell('Account settings', `<main class="dashboard-app">${accountMenuCss}${accountSettingsCss}${workbenchHeader(user, 'Account')}
  <div class="pc-main"><section class="pc-workspace"><div class="pc-settings-content"><header class="pc-settings-head"><h1>Account settings</h1><p>Manage your profile, sign-in security, and Pagecraft plan.</p></header>
  ${notice(input.error, input.message)}<div class="pc-settings-layout"><div class="pc-settings-nav" role="tablist" aria-label="Account settings"><button id="settings-tab-profile" type="button" role="tab" aria-controls="settings-panel-profile" data-settings-tab="profile" ${tabState('profile')}>Profile</button><button id="settings-tab-security" type="button" role="tab" aria-controls="settings-panel-security" data-settings-tab="security" ${tabState('security')}>Security</button><button id="settings-tab-plan" type="button" role="tab" aria-controls="settings-panel-plan" data-settings-tab="plan" ${tabState('plan')}>Plan &amp; billing</button></div><div class="pc-settings-main">
  <section class="pc-settings-section" id="settings-panel-profile" role="tabpanel" aria-labelledby="settings-tab-profile" tabindex="0" data-settings-panel="profile"><div class="pc-settings-title"><div><h2>Profile</h2><p>Your verified email is used for sign-in, collaboration invitations, and account notices.</p></div>${joinedCopy ? `<span class="pc-account-meta">Joined ${esc(joinedCopy)}</span>` : ''}</div>
  <form class="pc-settings-form" method="post" action="/account/profile"><div class="pc-settings-field"><label for="account-name">Display name</label><input id="account-name" name="name" value="${esc(user.name)}" maxlength="120" autocomplete="name" required></div><div class="pc-settings-field"><label for="account-email">Email address</label><input id="account-email" name="email" type="email" value="${esc(user.email)}" maxlength="254" autocomplete="email" required><small>Changing this address requires confirmation before it becomes your Pagecraft sign-in.</small></div><div class="pc-settings-actions"><button class="pc-btn primary" type="submit">Save profile</button></div></form>
  <div class="pc-provider-list" aria-label="Sign-in methods"><div class="pc-provider"><strong>Email and password</strong><span>${hasPassword ? 'Connected' : 'Not set'}</span></div><div class="pc-provider"><strong>Google</strong><span>${providers.has('google') ? 'Connected' : 'Not connected'}</span></div></div></section>
  <section class="pc-settings-section" id="settings-panel-security" role="tabpanel" aria-labelledby="settings-tab-security" tabindex="0" data-settings-panel="security"><div class="pc-settings-title"><div><h2>${hasPassword ? 'Change password' : 'Set a password'}</h2><p>${hasPassword ? 'Use your current password to protect this change.' : 'Add email and password as another way to access your account.'}</p></div></div><form class="pc-settings-form" method="post" action="/account/password">
  ${hasPassword ? '<div class="pc-settings-field"><label for="current-password">Current password</label><input id="current-password" name="currentPassword" type="password" autocomplete="current-password" required></div>' : ''}<div class="pc-settings-field"><label for="new-password">New password</label><input id="new-password" name="password" type="password" minlength="12" autocomplete="new-password" aria-describedby="new-password-help" required><small id="new-password-help">At least 12 characters. Passphrases are welcome.</small></div><div class="pc-settings-field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" name="passwordConfirm" type="password" minlength="12" autocomplete="new-password" required></div><div class="pc-settings-actions"><button class="pc-btn primary" type="submit">${hasPassword ? 'Change password' : 'Set password'}</button></div></form></section>
  <section class="pc-settings-section" id="settings-panel-plan" role="tabpanel" aria-labelledby="settings-tab-plan" tabindex="0" data-settings-panel="plan"><div class="pc-settings-title"><div><h2>Plan &amp; billing</h2><p>Your current Pagecraft allowances and usage.</p></div><span class="pc-plan-badge">Free</span></div><div class="pc-plan-price">$0 <span>current plan</span></div><div class="pc-plan-limits"><div class="pc-usage-row"><div class="pc-usage-copy"><span>Owned sites</span><span>${data.ownerCount} of 3 used</span></div><div class="pc-usage-track" role="meter" aria-label="Owned sites used" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${data.ownerCount}"><span style="width:${sitePercent}%"></span></div></div><div class="pc-usage-row"><div class="pc-usage-copy"><span>Media storage</span><span>${esc(mediaSize(data.storage.usedBytes))} of ${esc(mediaSize(data.storage.limitBytes))}</span></div><div class="pc-usage-track" role="meter" aria-label="Media storage used" aria-valuemin="0" aria-valuemax="${data.storage.limitBytes}" aria-valuenow="${data.storage.usedBytes}"><span style="width:${storagePercent}%"></span></div></div></div><ul class="pc-plan-list"><li>Up to 3 owned sites</li><li>100 MB optimized media storage</li><li>Storage shared across owned sites</li><li>Collaborator sites do not use your site allowance</li></ul><p class="pc-plan-note">Paid plans are not available yet. No payment method is required for the Free plan.</p></section>
  <div class="pc-settings-links"><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Service</a><a href="mailto:hello@braudyp.dev">Contact support</a></div></div></div></div></section></div></main><script>(()=>{
    const tabs=[...document.querySelectorAll('[data-settings-tab]')],panels=[...document.querySelectorAll('[data-settings-panel]')];
    if(!tabs.length||!panels.length)return;
    const names=new Set(tabs.map(tab=>tab.dataset.settingsTab));
    const activate=(name,focus=false)=>{if(!names.has(name))return;tabs.forEach(tab=>{const selected=tab.dataset.settingsTab===name;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;if(selected&&focus)tab.focus();});panels.forEach(panel=>{panel.hidden=panel.dataset.settingsPanel!==name;});};
    tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(tab.dataset.settingsTab));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activate(tabs[next].dataset.settingsTab,true);});});
    const selected=tabs.find(tab=>tab.getAttribute('aria-selected')==='true')?.dataset.settingsTab||'profile',legacy=location.hash.slice(1);activate(names.has(legacy)?legacy:selected);if(legacy&&names.has(legacy))history.replaceState(null,'',location.pathname+location.search);
  })();</script>`);
};

export const dashboardPage = (
  user: User, sites: DashboardSite[], ownerCount: number, storage: DashboardStorage,
  error?: string, message?: string
) => {
  const atLimit = ownerCount >= 3;
  const remaining = Math.max(0, 3 - ownerCount);
  const cards = sites.map(site => `<article class="pc-site-card" data-site-card data-name="${esc(site.name.toLowerCase())}" data-updated="${esc(site.updatedAt)}" data-role="${esc(site.role)}">
    <div class="pc-site-preview"><div class="pc-preview-fallback" aria-hidden="true">${builderMark}<span>Loading site preview…</span></div><iframe src="${esc(site.url)}" loading="lazy" tabindex="-1" aria-hidden="true" title=""></iframe><details class="pc-site-menu"><summary aria-label="More actions for ${esc(site.name)}"><svg width="18" height="18" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><circle cx="3" cy="8" r="1.2"/><circle cx="8" cy="8" r="1.2"/><circle cx="13" cy="8" r="1.2"/></svg></summary><div class="pc-site-menu-panel"><a href="/sites/${encodeURIComponent(site.id)}">Manage site</a><button type="button" data-copy-site data-url="${esc(site.url)}">Copy public link</button></div></details></div>
    <div class="pc-site-copy"><div class="pc-site-meta"><div><div class="pc-site-name">${esc(site.name)}</div><a class="pc-site-url" href="${esc(site.url)}" target="_blank" rel="noopener" title="${esc(site.url)}">${esc(site.url.replace(/^https?:\/\//, '').replace(/\/$/, ''))}</a><div class="pc-site-time">Edited ${esc(relativeTime(site.updatedAt))}</div></div><div><div class="pc-site-state ${site.published ? '' : 'draft'}">${site.published ? 'Published' : 'Draft changes'}</div><div class="pc-site-role">${site.role === 'owner' ? 'Owner' : 'Content'}</div></div></div>
    <div class="pc-site-actions"><a class="pc-btn primary" href="/edit/${encodeURIComponent(site.id)}">Edit</a><a class="pc-btn" href="${esc(site.url)}" target="_blank" rel="noopener">View site</a></div></div>
  </article>`).join('');
  const createCard = atLimit
    ? `<div class="pc-create-card pc-limit-card"><div><div class="pc-create-icon">${sitesIcon}</div><h2>Site limit reached</h2><p>${esc(messages.limit)}</p></div></div>`
    : `<details class="pc-create-card" id="create-site" ${sites.length ? '' : 'open'}><summary><span class="pc-create-icon"><svg width="24" height="24" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M8 2.5v11M2.5 8h11"/></svg></span><h2>${sites.length ? 'Create a new site' : 'Create your first site'}</h2><p>${remaining} ${remaining === 1 ? 'site' : 'sites'} remaining</p></summary><form class="pc-create-form" method="post" action="/api/sites" data-create-form><div class="pc-create-field"><label for="site-name">Site name</label><input id="site-name" name="name" placeholder="My new site" maxlength="120" required></div><div class="pc-create-field"><label for="site-slug">Site address <span aria-hidden="true">(optional)</span></label><input id="site-slug" name="slug" placeholder="my-new-site" maxlength="40" spellcheck="false" autocapitalize="none" aria-describedby="site-slug-help"><small id="site-slug-help">Lowercase letters, numbers, and single hyphens. Leave blank to generate it from the name.</small></div><div class="pc-create-error" data-create-error role="alert" hidden></div><button class="pc-btn primary" type="submit">Create site</button></form></details>`;
  const newSiteAction = atLimit
    ? `<button class="pc-btn primary" type="button" disabled>Add new site</button>`
    : `<a class="pc-btn primary" href="#create-site" data-create-open>Add new site</a>`;
  return shell('Sites', `<main class="dashboard-app">${accountMenuCss}${workbenchHeader(user, 'Sites')}
  <div class="pc-main"><nav class="pc-rail" aria-label="Sites navigation"><button type="button" data-site-view="sites" aria-pressed="true">${sitesIcon}<span>Sites</span></button><button type="button" data-site-view="owned" aria-pressed="false">${ownedIcon}<span>Owned</span></button><button type="button" data-site-view="shared" aria-pressed="false">${sharedIcon}<span>Shared</span></button><span class="pc-rail-gap"></span></nav>
  <section class="pc-workspace"><div class="pc-content"><header class="pc-heading"><h1>Sites</h1><p>Manage and continue building your Pagecraft sites.</p></header>
  <div class="pc-toolbar"><label class="pc-search"><span class="sr-only">Search sites</span><svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><circle cx="7" cy="7" r="4.5"/><path d="M10.5 10.5L14 14" stroke-linecap="round"/></svg><input type="search" placeholder="Search sites" data-site-search></label><label><span class="sr-only">Sort sites</span><select class="pc-sort" data-site-sort><option value="updated">Last edited</option><option value="name">Name</option></select></label>${newSiteAction}</div>
  ${notice(error, message)}<div class="pc-results-row"><p class="pc-results" aria-live="polite" data-site-results>${sites.length} ${sites.length === 1 ? 'site' : 'sites'}</p><span class="pc-allowance">${ownerCount} of 3 owned sites · ${esc(mediaSize(storage.usedBytes))} of ${esc(mediaSize(storage.limitBytes))} media used</span></div><section class="pc-site-grid" aria-label="Sites" data-site-grid>${cards}${!sites.length ? `<div class="pc-empty-copy"><h2>Start with a blank site</h2><p>Your builder opens after the site is created. You will still return here whenever you sign in.</p></div>` : ''}<div class="pc-filter-empty" data-filter-empty hidden><h2 data-filter-title>No sites found</h2><p data-filter-copy></p><button class="pc-btn" type="button" data-filter-action>Show all sites</button></div>${createCard}</section></div></section></div>
  </main><script>(()=>{
    const cards=[...document.querySelectorAll('[data-site-card]')],grid=document.querySelector('[data-site-grid]'),search=document.querySelector('[data-site-search]'),sort=document.querySelector('[data-site-sort]'),results=document.querySelector('[data-site-results]'),createCard=document.querySelector('.pc-create-card'),createForm=document.querySelector('[data-create-form]'),createError=document.querySelector('[data-create-error]'),empty=document.querySelector('[data-filter-empty]'),emptyTitle=document.querySelector('[data-filter-title]'),emptyCopy=document.querySelector('[data-filter-copy]'),emptyAction=document.querySelector('[data-filter-action]');
    let view='sites',emptyMode='all';
    const setView=next=>{view=next;document.querySelectorAll('[data-site-view]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.siteView===view)));apply();};
    const apply=()=>{
      const query=(search?.value||'').trim().toLowerCase();
      let visible=cards.filter(card=>(!query||card.dataset.name.includes(query))&&(view!=='owned'||card.dataset.role==='owner')&&(view!=='shared'||card.dataset.role!=='owner'));
      for(const card of cards)card.hidden=!visible.includes(card);
      visible.sort((a,b)=>sort?.value==='name'?a.dataset.name.localeCompare(b.dataset.name):new Date(b.dataset.updated).getTime()-new Date(a.dataset.updated).getTime());
      for(const card of visible)grid?.insertBefore(card,grid.querySelector('.pc-empty-copy,.pc-filter-empty,.pc-create-card'));
      if(results)results.textContent=visible.length+' '+(visible.length===1?'site':'sites');
      if(createCard)createCard.hidden=view==='shared';
      if(!empty)return;
      empty.hidden=visible.length>0||cards.length===0;
      if(empty.hidden)return;
      if(query){emptyMode='search';emptyTitle.textContent='No sites match your search';emptyCopy.textContent='Try another site name or clear the current search.';emptyAction.textContent='Clear search';}
      else if(view==='shared'){emptyMode='all';emptyTitle.textContent='No shared sites yet';emptyCopy.textContent='Sites shared with you will appear here.';emptyAction.textContent='Show all sites';}
      else if(view==='owned'){emptyMode='create';emptyTitle.textContent='No owned sites yet';emptyCopy.textContent='Create a site to start building under your account.';emptyAction.textContent='Create a site';}
      else{emptyMode='all';emptyTitle.textContent='No sites found';emptyCopy.textContent='Return to all sites and try again.';emptyAction.textContent='Show all sites';}
    };
    search?.addEventListener('input',apply);sort?.addEventListener('change',apply);
    document.querySelectorAll('[data-site-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.siteView)));
    document.querySelectorAll('[data-create-open]').forEach(link=>link.addEventListener('click',()=>{const details=document.querySelector('#create-site');if(details){details.hidden=false;details.open=true;requestAnimationFrame(()=>details.querySelector('input')?.focus());}}));
    emptyAction?.addEventListener('click',()=>{if(emptyMode==='search'){search.value='';search.focus();apply();return;}if(emptyMode==='create'){const details=document.querySelector('#create-site');if(details){details.hidden=false;details.open=true;requestAnimationFrame(()=>details.querySelector('input')?.focus());}return;}setView('sites');});
    document.querySelectorAll('.pc-site-preview').forEach(preview=>{const frame=preview.querySelector('iframe'),label=preview.querySelector('.pc-preview-fallback span');if(!frame)return;const ready=()=>{preview.classList.add('is-ready');};const failed=()=>{preview.classList.remove('is-ready');if(label)label.textContent='Preview unavailable';};frame.addEventListener('load',ready,{once:true});frame.addEventListener('error',failed,{once:true});setTimeout(()=>{if(!preview.classList.contains('is-ready'))failed();},7000);});
    document.querySelectorAll('[data-copy-site]').forEach(button=>button.addEventListener('click',async()=>{const url=button.dataset.url||'';try{await navigator.clipboard.writeText(url);}catch{const field=document.createElement('textarea');field.value=url;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();document.execCommand('copy');field.remove();}const previous=button.textContent;button.textContent='Link copied';setTimeout(()=>button.textContent=previous,1800);}));
    createForm?.addEventListener('submit',async event=>{event.preventDefault();if(!createForm.reportValidity())return;const button=createForm.querySelector('button[type="submit"]'),data=new FormData(createForm),name=String(data.get('name')||'').trim(),slug=String(data.get('slug')||'').trim();if(createError){createError.hidden=true;createError.textContent='';}if(slug&&!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)){if(createError){createError.textContent='Use lowercase letters, numbers, and single hyphens. Maximum 40 characters.';createError.hidden=false;}createForm.querySelector('[name="slug"]')?.focus();return;}button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Creating…';try{const response=await fetch('/api/sites',{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({name,...(slug?{slug}:{})})});const payload=await response.json().catch(()=>({}));if(response.ok&&payload.id){location.href='/edit/'+encodeURIComponent(payload.id);return;}const copy={invalid_slug:'Use lowercase letters, numbers, and single hyphens. Maximum 40 characters.',slug_taken:'That site address is already in use. Choose another.',site_limit_reached:'You can create up to three owned sites.',profile_missing:'Your Pagecraft profile is not ready. Sign out and sign in again, or contact support.',site_creation_unavailable:'Site creation is temporarily unavailable. Your existing sites are still available.'};if(createError){createError.textContent=payload.detail||copy[payload.error]||'We could not create that site. Try again.';createError.hidden=false;}if(payload.error==='invalid_slug'||payload.error==='slug_taken')createForm.querySelector('[name="slug"]')?.focus();}catch{if(createError){createError.textContent='We could not reach Pagecraft. Check your connection and try again.';createError.hidden=false;}}finally{button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Create site';}});
  })();</script>`);
};
